/* FEATURE_TOUR_START */
/* FEATURE_CORE_START */
const FeatureCore={steps:[
 ['AI 助手','用一句目标搭出工作区','执行预设的本地示范，画板上会真正出现项目、成员、笔记与草稿。','让助手搭建示范'],
 ['AI 助手','亲手暂停，再继续','在助手里点击暂停，再继续未完成步骤。已经完成的创建步骤不会重复。','打开助手进度'],
 ['开源工具库','按项目目标找合适的方法','打开真实目录，查看按当前练习项目推荐的条目。索引不代表工具已经安装。','打开项目能力库'],
 ['开源工具库','看来源、正文与更新边界','阅读教学节选，体验一次模拟刷新。真实目录每周五检查，可手动更新，不是持续爬取全网。','查看来源与更新教学'],
 ['Prompt 优化','从原话出发选 Skill','点击“开始推敲”看预设示例：理解请求、选择方法、读取正文、说明采用理由，不套统一模板。','打开 Prompt 推敲'],
 ['Prompt 优化','把结果交给项目','点击“放入项目草稿”。只写入草稿，不会替你发送，也可以撤销。','查看并应用优化结果'],
 ['授权接力','认识本人验证与原断点恢复','查看上方实机状态，再完成下方标明“本地模拟”的验证、合并、接续与取消。不会改变真实授权。','打开授权与接力教学'],
 ['授权接力','回到真正的工作区','工具已介绍完。权限范围与有效期由本人在原生面板确认，助手不会扩大授权或拿取密码、验证码。','完成亮点工具实操']
 ],done(s,t,assistant){if(!t)return false;switch(t.step){case 0:return s.projects.some(p=>p.id===t.projectId)&&s.projects.some(p=>p.id===t.reviewId);case 1:return!!t.flags.paused&&assistant?.status==='completed';case 2:return!!t.flags.library;case 3:return!!t.flags.read&&!!t.flags.refresh;case 4:return!!t.flags.refined;case 5:return!!t.flags.applied;case 6:return!!t.flags.authResumed&&!!t.flags.authCanceled;case 7:return true;default:return false}}};
/* FEATURE_CORE_END */
const featureCoach=document.createElement('section');featureCoach.id='feature-coach';featureCoach.className='fl';featureCoach.hidden=true;featureCoach.setAttribute('aria-label','亮点工具实操');document.body.append(featureCoach);
let featurePainting=false;
const featureSession=()=>state.featureTour;
const featureActive=()=>featureSession()?.status==='active';
function featureDone(){return FeatureCore.done(state,featureSession(),state.assistantSessions.find(s=>s.id===featureSession()?.assistantId))}
function featureBegin(){if(AS.ac)return hint('先暂停当前助手任务，再开始本地实操');asCloseAux();$('#guide').classList.remove('o');if(state.tutorial?.status==='active')tutorialPause();if(!featureSession()||featureSession().status==='complete'||!state.boards.some(b=>b.id===featureSession().boardId)){state.featureTour={id:'ft'+uid(),status:'active',step:0,flags:{},original:{boardId:state.activeBoard,room:state.room,sel:state.sel}};act('board.create',{name:'亮点工具 · 本地实操'});featureSession().boardId=state.activeBoard;B().tutorialSessionId=featureSession().id;B().featurePractice=true;}else{featureSession().status='active';state.activeBoard=featureSession().boardId;state.room=null;}save();renderAll();featurePaint()}
async function featureDemo(){const t=featureSession();if(t.assistantId){AS.current=t.assistantId;$('#guide').classList.add('o');renderGuide();return}const ref=(id,field)=>({$ref:id+'.'+field});const raw=[
 ['project.create','建立选题制作项目',{name:'选题与制作',boardId:t.boardId,x:240,y:340}],
 ['project.update','明确内容目标',{projectId:ref('s1','projectId'),summary:'为首次发大件的小店主制作清晰内容，不编造价格和客户经历'}],
 ['member.add','加入选题策划',{projectId:ref('s1','projectId'),agent:'gpt'}],
 ['member.update','写清成员职责',{projectId:ref('s1','projectId'),memberId:ref('s3','memberId'),name:'选题策划',role:'依据需求给出三个选题方向'}],
 ['project.create','建立审核接续项目',{name:'审核与接续',boardId:t.boardId,x:660,y:340}],
 ['note.create','留下事实边界笔记',{projectId:ref('s1','projectId'),text:'教学示例：不编造运费、时效或客户经历；本轮不真实发布。'}],
 ['assistant.draft','写入可见的项目草稿',{projectId:ref('s1','projectId'),text:'请根据练习需求，给第一次发大件的小店主准备三个选题，并说明不能编造的内容。本轮仅本地演练。'}],
 ['assistant.demo','演示一段可暂停的整理过程',{}],
 ['view.fit','展示本轮画板成果',{}]
 ];const s={id:'as'+uid(),demo:true,boardId:t.boardId,request:'【固定目标·本地示范】搭建内容制作与审核工作区，准备成员、笔记和草稿。',reply:'这一轮用预设计划演示软件控制，没有调用AI模型；每一步都会实际改变练习画板。',steps:raw.map(([name,label,args],i)=>({id:'s'+(i+1),name,label,args,effect:'local',status:'pending'})),cursor:0,status:'ready',createdAt:Date.now()};state.assistantSessions.push(s);t.assistantId=s.id;AS.current=s.id;$('#guide').classList.add('o');void asExecute(s);featurePaint()}
function featureLocalRefine(){const t=featureSession(),simple=(originalPrompt||'').trim().length<12;t.flags.refined=true;refineResult={text:simple?'谢谢你的帮助。':'请为第一次发大件的小店主准备3个自媒体选题，每个附一句适合口播的说明。保持清楚友好，只使用已给材料，不编造运费、时效或客户经历。先交人工审核，本轮不发布。',intent:'【本地预设示例】澄清受众、交付与事实边界',skills:simple?[]:[{id:'feature-scope',title:'需求澄清方法（教学示例）',reason:'本示例需要补清受众和不可编造的内容',source:'本地教学节选'}],application:simple?[]:[{id:'feature-scope',used:'先识别已有约束，再补必要交付；没有强制长模板。真实模式会语义路由并读取被选Skill正文。'}],changes:['本轮结果来自预设教学样例，没有调用模型'],questions:[],engine:'local-demo'};$('#prompt-result').value=refineResult.text;$('#refine-phase').textContent='本地预设示例 · 真实模式才由模型理解和选择 Skill';showRefineEvidence();featurePaint()}
const featureRefineBase=runRefinement;runRefinement=function(){if(featureActive()&&B()?.id===featureSession().boardId){originalPrompt=$('#prompt-original').value;featureLocalRefine();return}return featureRefineBase()};
const featurePauseBase=asPause;asPause=function(){const t=featureSession();if(featureActive()&&asSession()?.id===t.assistantId)t.flags.paused=true;featurePauseBase();featurePaint()};
async function featureAction(){const t=featureSession();if(!featureActive())return;switch(t.step){
 case 0:await featureDemo();break;
 case 1:AS.current=t.assistantId;$('#guide').classList.add('o');renderGuide();break;
 case 2:case 3:if(!P(t.projectId))return hint('先完成助手建板示范');sbOpen(t.projectId);break;
 case 4:case 5:state.sel=t.projectId;state.room=null;openUtility('prompt','帮我准备给第一次发大件的小店主看的自媒体选题，别编价格或客户故事。');break;
 case 6:openUtility('auth');break;
 case 7:featureFinish();return;
 }save();featurePaint()}
function featureFinish(){asPause();asCloseAux();$('#guide').classList.remove('o');const t=featureSession();t.status='complete';if(state.boards.some(b=>b.id===t.original.boardId)){state.activeBoard=t.original.boardId;state.room=P(t.original.room)?t.original.room:null;state.sel=P(t.original.sel)?t.original.sel:null}save();renderAll();tutorialOpenHome();featurePaint()}
function featurePause(){asPause();asCloseAux();$('#guide').classList.remove('o');const t=featureSession();if(t){t.status='paused';if(state.boards.some(b=>b.id===t.original.boardId)){state.activeBoard=t.original.boardId;state.room=P(t.original.room)?t.original.room:null;state.sel=P(t.original.sel)?t.original.sel:null}}save();renderAll();featurePaint()}
function featureMarkup(t,inline=false){const row=FeatureCore.steps[t.step],done=featureDone();return `<div class="tm-head"><b>${esc(row[0])} · ${t.step+1}/${FeatureCore.steps.length}</b><span class="tm-sp"></span><button data-ft="pause" aria-label="暂停亮点实操">−</button></div><div class="tm-body"><span class="feature-sandbox">本地演练 · 不调模型 · 不改权限</span><h3>${esc(row[1])}</h3><p>${esc(row[2])}</p>${t.step===3&&inline?`<details open><summary>正文、来源与目录更新示例</summary><p class="feature-note">教学节选：先确定受众、交付和不可编造的事实。这里只展示本地方法示例，不冒充某条线上 Skill 的完整正文。</p><p class="feature-note">真实条目的来源与许可请点能力卡片查看；最近检查与每周日程在能力库左侧显示。</p><button data-ft="read">我已读过教学节选</button><button data-ft="refresh">模拟一次手动刷新</button></details>`:''}${t.step===6&&inline?`<div class="feature-step"><b>以下是预设模拟，上方是实机状态</b><p>${t.flags.authResumed?'3个任务已从各自断点接续':t.flags.authVerified?'本人验证已模拟完成，等待明确继续':'同站点3个任务等待一次本人验证'}</p><div class="row"><button data-ft="auth-verify">模拟本人完成验证</button><button data-ft="auth-resume" ${t.flags.authVerified?'':'disabled'}>从原断点继续</button><button data-ft="auth-cancel">模拟取消一个任务</button></div></div>`:''}${t.feedback?`<p class="feature-note" role="status">${esc(t.feedback)}</p>`:''}</div><div class="tm-foot">${inline||t.step===FeatureCore.steps.length-1?'':`<button data-ft="action">${icon('arrow',14)}${esc(row[3])}</button>`}${t.step<FeatureCore.steps.length-1?`<button data-ft="next" ${done?'':'disabled'}>${done?'已观察到，下一步':'先完成当前操作'}</button>`:`<button data-ft="action">完成并返回</button>`}</div>`}
function featurePaint(){if(featurePainting)return;featurePainting=true;try{const t=featureSession();document.querySelectorAll('.feature-inline').forEach(e=>e.remove());document.querySelectorAll('.feature-host').forEach(e=>e.classList.remove('feature-host'));if(!featureActive()){featureCoach.hidden=true;return}const s=state.assistantSessions.find(s=>s.id===t.assistantId);if(s?.results?.s1?.projectId)t.projectId=s.results.s1.projectId;if(s?.results?.s5?.projectId)t.reviewId=s.results.s5.projectId;if(t.step===2)t.flags.library=!!(skillbook.open&&SB.projectId===t.projectId&&SB.stats?.resources>0&&SB.entries.length);if(t.step===5&&refineResult?.text&&P(t.projectId)?.ui.composerDraft===refineResult.text)t.flags.applied=true;if(t.step===5&&(!refineResult?.text||P(t.projectId)?.ui.composerDraft!==refineResult.text))t.flags.applied=false;const host=skillbook.open?skillbook:modelConnect.open?modelConnect:utility.classList.contains('o')?utility:$('#guide').classList.contains('o')?$('#guide'):null;featureCoach.hidden=!!host;if(host){host.classList.add('feature-host');const b=document.createElement('section');b.className='feature-inline';b.innerHTML=featureMarkup(t,true);host.append(b)}else featureCoach.innerHTML=featureMarkup(t);dmDecorate()}finally{featurePainting=false}}
const featureHomeBase=tutorialHomeMarkup;tutorialHomeMarkup=function(v){const t=featureSession();return featureHomeBase(v).replace('<div class="tm-acts">',`<section class="feature-entry"><h3>亮点工具实操</h3><p>4关：AI助手、持续更新工具库、Skill推敲Prompt、授权接力。独立于${TutorialCore.steps.length}步自媒体课程。</p><button data-ft="begin">${t?.status==='active'||t?.status==='paused'?'继续亮点实操 '+(t.step+1)+'/8':'体验亮点工具实操'}</button>${t?.status==='complete'?'<small>已完成 · 可以再开一轮</small>':''}</section><div class="tm-acts">`)};
const featureWindowsBase=dmWindows;dmWindows=function(){return[...featureWindowsBase(),featureCoach]};
const featureAllBase=renderAll;renderAll=function(){featureAllBase();featurePaint()};
const featureGuideBase=renderGuide;renderGuide=function(){featureGuideBase();featurePaint()};
document.addEventListener('click',e=>{const b=e.target.closest('[data-ft]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const t=featureSession();switch(b.dataset.ft){case'begin':featureBegin();return;case'pause':featurePause();return;case'action':void featureAction();return;case'next':if(!featureDone())return hint('先完成当前的可见操作');asCloseAux();$('#guide').classList.remove('o');t.step++;t.feedback='';break;case'read':t.flags.read=true;t.feedback='已阅读教学节选，真实入口可核对完整来源与许可';break;case'refresh':t.flags.refresh=true;t.feedback='已模拟一次刷新；实机目录和每周日程没有更改';break;case'auth-verify':t.flags.authVerified=true;t.feedback='仅模拟本人验证完成，未操作任何真实账号';break;case'auth-resume':if(t.flags.authVerified)t.flags.authResumed=true;break;case'auth-cancel':t.flags.authCanceled=true;t.feedback='已模拟取消一个任务，另外两个保留各自断点';break}save();featurePaint()},true);
let featureFrame=0;new MutationObserver(()=>{if(!featureFrame){featureFrame=requestAnimationFrame(()=>{featureFrame=0;if(featureActive()){const host=skillbook.open?skillbook:utility.classList.contains('o')?utility:$('#guide').classList.contains('o')?$('#guide'):null;if(host&&!host.querySelector('.feature-inline'))featurePaint()}})}}).observe(document.body,{childList:true,subtree:true});
/* FEATURE_TOUR_END */
